struct Config {
    query: String,
    file_path: String,
    ignore_case: bool,
}

impl Config {
    fn build(args: &[String]) -> Result<Config, String> {
        if args.len() < 3 {
            return Err(String::from("not enough arguments"));
        }
        if args.len() > 4 {
            return Err(String::from("too many arguments"));
        }
        let query = args[1].clone();
        let file_path = args[2].clone();
        let ignore_case = match args.get(3).map(|s| s.as_str()) {
            None => false,
            Some("--ignore-case") => true,
            Some(other) => return Err(format!("unknown option: {other}")),
        };
        Ok(Config { query, file_path, ignore_case })
    }
}

fn main() {
    let runs = [
        vec!["minigrep", "frog", "poem.txt"],
        vec!["minigrep", "frog", "poem.txt", "--ignore-case"],
        vec!["minigrep", "frog", "poem.txt", "-x"],
        vec!["minigrep", "frog", "poem.txt", "--ignore-case", "more"],
    ];
    for run in runs {
        let args: Vec<String> = run.iter().map(|s| s.to_string()).collect();
        match Config::build(&args) {
            Ok(c) => println!("{}/{}/{}", c.query, c.file_path, c.ignore_case),
